"use strict";

/* Spoken letters, base64 MP3, keyed voice → letter.

   Rendered locally with flite and its CMU voices (slt, rms, awb, kal), which are
   permissively licensed. Nothing was downloaded and nothing third-party is
   redistributed here. The obvious shortcut — lifting the clips another open-source
   n-back uses — does not work: that project's MIT licence covers its code, while its
   audio is fetched at build time from a third party's server, so those terms are not
   the project's to grant.

   Its own file rather than a lump inside constants.js: it is 78KB of opaque data and
   would bury everything around it. Base64 rather than a folder of files because the
   app has to keep working from file://, where fetching a sibling is blocked; MP3
   rather than the half-as-large Opus because Opus-in-Ogg fails SILENTLY on older
   Safari, and absent audio is worse than bigger audio. */
const LETTER_AUDIO = {
  slt: {A:"", F:"", L:"", O:"", Q:"", R:"", X:"", Y:""},
  rms: {A:"", F:"", L:"", O:"", Q:"", R:"", X:"", Y:""},
  awb: {A:"", F:"", L:"", O:"", Q:"", R:"", X:"", Y:""},
  kal: {A:"", F:"", L:"", O:"", Q:"", R:"", X:"", Y:""},
};
